	private static ModelPart part(float x, float y, float z, Map<String, ModelPart> children, List<ModelPart.Cube> cubes) {
		ModelPart part = new ModelPart(cubes, children);
		part.setPos(x, y, z);
		part.setInitialPose(part.storePose());
		return part;
	}

	private static Map<String, ModelPart> hand(float x, float y, float z) {
		ModelPart hand = new ModelPart(List.of(), Map.of());
		hand.setPos(x, y, z);
		hand.setInitialPose(hand.storePose());
		return Map.of("hand", hand);
	}

	/** One cube. Each float array is four corners: x, y, z, u, v. u and v are 0–1. */
	private static ModelPart.Cube cube(List<float[]> faces) {
		float minX = Float.POSITIVE_INFINITY, minY = Float.POSITIVE_INFINITY, minZ = Float.POSITIVE_INFINITY;
		float maxX = Float.NEGATIVE_INFINITY, maxY = Float.NEGATIVE_INFINITY, maxZ = Float.NEGATIVE_INFINITY;
		for (float[] face : faces) {
			for (int i = 0; i < 4; i++) {
				float x = face[i * 5], y = face[i * 5 + 1], z = face[i * 5 + 2];
				minX = Math.min(minX, x); minY = Math.min(minY, y); minZ = Math.min(minZ, z);
				maxX = Math.max(maxX, x); maxY = Math.max(maxY, y); maxZ = Math.max(maxZ, z);
			}
		}
		ModelPart.Cube box = new ModelPart.Cube(
				0, 0, minX, minY, minZ, Math.max(0.001f, maxX - minX), Math.max(0.001f, maxY - minY), Math.max(0.001f, maxZ - minZ),
				0.0f, 0.0f, 0.0f, false, 16.0f, 16.0f, java.util.EnumSet.allOf(Direction.class));
		int count = Math.min(6, Math.min(faces.size(), box.polygons.length));
		for (int i = 0; i < count; i++) {
			float[] face = faces.get(i);
			ModelPart.Vertex[] vertices = new ModelPart.Vertex[4];
			for (int v = 0; v < 4; v++) {
				int o = v * 5;
				vertices[v] = new ModelPart.Vertex(face[o], face[o + 1], face[o + 2], face[o + 3], face[o + 4]);
			}
			Vector3f a = new Vector3f(vertices[1].x() - vertices[0].x(), vertices[1].y() - vertices[0].y(), vertices[1].z() - vertices[0].z());
			Vector3f b = new Vector3f(vertices[2].x() - vertices[0].x(), vertices[2].y() - vertices[0].y(), vertices[2].z() - vertices[0].z());
			Vector3f normal = a.cross(b);
			if (normal.lengthSquared() > 1.0E-6f) {
				normal.normalize();
			}
			box.polygons[i] = new ModelPart.Polygon(vertices, normal);
		}
		return box;
	}

	@Override
	public void setupAnim(HellBerserkRenderState state) {
		this.resetPose();
		// yRot here is already "where the head looks" minus "where the body faces".
		// Subtracting bodyRot again turns the head backward while he chases.
		this.head.xRot = state.xRot * ((float) Math.PI / 180.0f);
		this.head.yRot = state.yRot * ((float) Math.PI / 180.0f);
		float swing = state.walkAnimationPos;
		float amount = state.walkAnimationSpeed;
		// Same step as a piglin. Right leg and left arm together, then the other pair.
		this.rightArm.xRot = Mth.cos(swing * 0.6662f + (float) Math.PI) * amount;
		this.leftArm.xRot = Mth.cos(swing * 0.6662f) * amount;
		this.rightLeg.xRot = Mth.cos(swing * 0.6662f) * 1.4f * amount;
		this.leftLeg.xRot = Mth.cos(swing * 0.6662f + (float) Math.PI) * 1.4f * amount;
		if (!state.aggressive) {
			return;
		}
		if (state.swingAnimation > 0.0f) {
			AnimationUtils.swingWeaponDown(this.rightArm, this.leftArm, HumanoidArm.RIGHT, state.swingAnimation, state.ageInTicks);
		} else {
			// Axe held up, the way a brute holds his before the swing.
			this.rightArm.xRot = -1.8f;
		}
	}
